SET SERVEROUTPUT ON
DECLARE
score PLS_INTEGER := 8;
BEGIN
IF score >= 5 THEN
 DBMS_OUTPUT.PUT_LINE('Pass');
ELSE
 DBMS_OUTPUT.PUT_LINE('Try again');
END IF;
END;
/

SET SERVEROUTPUT ON
DECLARE
light VARCHAR2(10) := 'green';
BEGIN
CASE light
 WHEN 'red' THEN DBMS_OUTPUT.PUT_LINE('Stop');
 WHEN 'green' THEN DBMS_OUTPUT.PUT_LINE('Go');
 ELSE DBMS_OUTPUT.PUT_LINE('Wait');
END CASE;
END;
/

SET SERVEROUTPUT ON
BEGIN
 FOR n IN 1..3 LOOP
  DBMS_OUTPUT.PUT_LINE(n);
 END LOOP;
END;
/

SET SERVEROUTPUT ON
DECLARE
n PLS_INTEGER := 1;
BEGIN
WHILE n <= 3 LOOP
 DBMS_OUTPUT.PUT_LINE(n);
 n := n + 1;
END LOOP;
END;
/

SET SERVEROUTPUT ON
DECLARE
TYPE book_type IS RECORD (title VARCHAR2(30), pages PLS_INTEGER);
book book_type;
BEGIN
book.title := 'Moon Trip';
book.pages := 24;
DBMS_OUTPUT.PUT_LINE(book.pages);
END;
/

SET SERVEROUTPUT ON
DECLARE
TYPE scores_type IS TABLE OF PLS_INTEGER INDEX BY VARCHAR2(20);
scores scores_type;
BEGIN
scores('Asha') := 8;
DBMS_OUTPUT.PUT_LINE(scores('Asha'));
END;
/

SET SERVEROUTPUT ON
DECLARE
FUNCTION twice(n PLS_INTEGER) RETURN PLS_INTEGER IS
BEGIN
 RETURN n * 2;
END;
BEGIN
DBMS_OUTPUT.PUT_LINE(twice(4));
END;
/

SET SERVEROUTPUT ON
DECLARE
answer NUMBER;
BEGIN
answer := 1 / 0;
EXCEPTION
 WHEN ZERO_DIVIDE THEN DBMS_OUTPUT.PUT_LINE('Cannot divide by zero');
END;
/

